 ps=list(s['paras']);ps[1]+=' '+' '.join(USE[f] for f in forms);ps[2]+=' '+bridge(reviews);ps,text=fit(ps,lo,hi);P=base.prior(prior);new=[base.nt(f,text,deck) for f in forms];rev=[base.rev(f,P) for f in reviews];ids={t['form']:t['id'] for t in new+rev};q,a=base.qa(qs(s,forms),ids)
