def specs():return [
 {'id':'fr-c1-u09-p01','seq':49,'title':'Le retour transforme aussi le passé raconté','genre':'reflection','topics':['retrospective narration','temporal distance'],'paras':["Un témoin fictif revient après plusieurs décennies dans le quartier où il a grandi. Son récit alterne entre la description actuelle des rues et des épisodes qu’il attribue à son adolescence. La synthèse historique ne traite pas ces deux temps comme un seul plan : elle note ce que le retour présent peut révéler et ce qu’il risque de reconstruire.","Certaines affirmations portent sur des bâtiments encore observables; d’autres sur des conversations dont aucune trace indépendante n’existe. La distance temporelle ne rend pas automatiquement le récit faux, mais elle change le type de confiance que l’on peut lui accorder.","Le contreargument affirme que les hésitations du témoin rendent tout le récit inutilisable. Le texte répond qu’une source peut être précise sur certains éléments et incertaine sur d’autres. Les corrections spontanées et les distinctions entre voir, entendre et supposer peuvent même aider à évaluer la structure de la mémoire.","La conclusion produit une chronologie limitée : elle utilise le témoignage pour les expériences et repères qu’il décrit, puis marque séparément les affirmations qui demandent une autre source. Le retour n’est donc ni une preuve totale ni une simple fiction; il devient un document situé."],'qclaim':'Quelle distinction organise le récit de retour ?','aclaim':'Il faut séparer ce qui est observé au présent, ce qui est remémoré et ce qui est reconstruit rétrospectivement.','qinfer':'Pourquoi une hésitation n’annule-t-elle pas toute la source ?','ainfer':'Parce que la fiabilité peut varier selon les affirmations et l’hésitation peut rendre visibles les limites du souvenir.','qassume':'Que suppose l’usage historique d’un témoignage tardif ?','aassume':'Une distinction entre expériences directement rapportées, inférences et éléments vérifiables par d’autres traces.','qrelation':'Comment le texte répond-il à l’objection d’un récit inutilisable ?','arelation':'Il évalue les affirmations séparément au lieu d’accepter ou rejeter la source en bloc.','astance':'Utiliser le témoignage comme source située dont la portée varie selon le type d’affirmation.','asummary':'Le retour présent aide à organiser une mémoire tardive, mais la reconstruction historique conserve les limites et besoins de corroboration.'},
 {'id':'fr-c1-u09-p02','seq':50,'title':'Une histoire familiale peut dater un événement sans tout expliquer','genre':'historiographical essay','topics':['oral history','family chronology'],'paras':["Une famille fictive raconte depuis plusieurs générations qu’un incendie a changé son parcours. Les versions s’accordent sur une saison et sur le fait qu’un mariage important a suivi peu après, mais elles divergent sur la cause du feu et sur les personnes présentes. L’enquête utilise cette tradition orale comme point de départ plutôt que comme chronologie déjà résolue.","Les chercheurs comparent certificats, lettres, photographies datées et souvenirs. Les repères biographiques permettent de réduire certaines plages temporelles, tandis que les causes alléguées restent plus difficiles à établir. Une date et une explication n’exigent pas le même type de preuve.","Le contreargument affirme que les documents officiels devraient automatiquement l’emporter sur les récits familiaux. L’analyse refuse cette hiérarchie simple : un document peut dater une transaction ou un événement administratif sans enregistrer l’expérience vécue, tandis qu’un récit proche peut conserver un détail absent des formulaires.","La synthèse construit donc plusieurs couches : calendrier relativement solide, expériences attribuées à des personnes précises, et causes encore disputées. Ce modèle permet d’utiliser une mémoire familiale sans la transformer en archive exhaustive."],'qclaim':'Quelle méthode est appliquée à la mémoire familiale ?','aclaim':'La tradition orale sert à formuler et dater des questions, puis ses différentes affirmations sont comparées à des traces indépendantes.','qinfer':'Pourquoi une date peut-elle être mieux établie qu’une cause ?','ainfer':'Parce que des documents peuvent converger sur la chronologie sans enregistrer les mécanismes ou intentions.','qassume':'Que suppose la comparaison entre document et récit ?','aassume':'Que chacun possède un objectif et un accès à l’information différents.','qrelation':'Comment le texte traite-t-il l’idée que l’officiel l’emporte toujours ?','arelation':'Il compare la capacité de chaque source à soutenir l’affirmation précise au lieu d’imposer une hiérarchie générale.','astance':'Combiner oral et écrit selon le type de question et conserver les désaccords non résolus.','asummary':'La mémoire familiale peut stabiliser certains repères tout en laissant causes et responsabilités ouvertes.'},
 {'id':'fr-c1-u09-p03','seq':51,'title':'Source A : le rapport institutionnel voit la chaîne de commandement','genre':'source comparison','topics':['official source','conflict narrative'],'pair':PAIR,'paras':["La première source fictive est un rapport rédigé après un affrontement. Elle organise l’événement par unités, ordres reçus, mouvements et heures. Sa force est la structure : elle permet de reconstruire une chaîne de décisions et d’identifier ce que certains responsables affirment avoir demandé.","Cette précision a cependant une limite. Le document a été produit pour l’institution elle-même et privilégie ce qui entre dans ses catégories. Des expériences civiles, des hésitations locales ou des actions non signalées peuvent disparaître de la grille sans être nécessairement inexistantes.","Le contreargument affirme que la forme administrative rend le rapport plus fiable qu’un récit personnel. L’analyse distingue cohérence documentaire et vérité complète. Une chaîne d’ordres peut être bien enregistrée alors que l’exécution réelle, les perceptions sur place ou les conséquences pour d’autres groupes restent partielles.","La source est donc utilisée pour ce qu’elle observe bien : organisation, chronologie déclarée et vocabulaire institutionnel. Les affirmations sur l’ensemble de la scène restent comparées à d’autres traces."],'qclaim':'Quelle force principale possède la source A ?','aclaim':'Elle structure la chaîne de commandement, les heures et les mouvements déclarés.','qinfer':'Pourquoi ses catégories peuvent-elles créer des absences ?','ainfer':'Parce qu’elle enregistre surtout ce que l’institution était organisée pour signaler.','qassume':'Que suppose l’usage de la chronologie déclarée ?','aassume':'Qu’on la distingue de l’exécution réelle et qu’on la confronte lorsque d’autres traces existent.','qrelation':'Comment le texte répond-il à l’idée que l’administratif est nécessairement complet ?','arelation':'Il reconnaît la cohérence interne tout en limitant la portée aux dimensions réellement enregistrées.','astance':'Utiliser le rapport institutionnel pour ses forces spécifiques sans universaliser son point de vue.','asummary':'La source A éclaire la structure institutionnelle mais doit être complétée pour les expériences et conséquences hors de sa grille.'},
 {'id':'fr-c1-u09-p04','seq':52,'title':'Source B : le témoignage local voit des conséquences que le rapport classe mal','genre':'source comparison','topics':['civilian source','conflict narrative'],'pair':PAIR,'paras':["La seconde source fictive est un journal tenu par une personne vivant près du lieu de l’affrontement. Elle décrit sons, déplacements, personnes blessées et changements dans les routines quotidiennes. Elle possède une granularité sensorielle que le rapport institutionnel ne cherchait pas à produire.","Cette proximité ne rend pas le témoin omniscient. Il ne connaît pas tous les ordres, peut confondre deux groupes à distance et écrit sous stress. Le journal est particulièrement fort pour établir ce qui entre dans son champ d’expérience et plus faible lorsqu’il attribue des intentions à des acteurs éloignés.","Le contreargument affirme que les détails émotionnels rendent la source trop subjective. L’analyse répond que subjectivité et inutilité ne sont pas synonymes. Les réactions et descriptions locales sont précisément des données sur l’expérience, à condition de ne pas les transformer en carte complète du conflit.","La synthèse appariée montre alors une complémentarité partielle : la source A explique mieux la structure déclarée; la source B révèle mieux certaines conséquences locales. Elles se contredisent encore sur quelques heures et responsabilités, qui restent explicitement non résolues."],'qclaim':'Quelle force principale possède la source B ?','aclaim':'Elle documente avec précision certaines expériences et conséquences locales accessibles au témoin.','qinfer':'Pourquoi la proximité ne garantit-elle pas une vue complète ?','ainfer':'Parce que le témoin reste limité spatialement, informationnellement et émotionnellement.','qassume':'Que suppose l’usage des détails sensoriels ?','aassume':'Qu’ils servent à établir l’expérience observée sans être étendus automatiquement aux intentions ou à toute la scène.','qrelation':'Comment le texte répond-il à l’objection de subjectivité ?','arelation':'Il traite la perspective comme une caractéristique à situer plutôt que comme une raison de jeter la source.','astance':'Utiliser le témoignage pour l’expérience locale tout en limitant ses attributions causales.','asummary':'La source B complète le rapport institutionnel sur les conséquences locales mais ne résout pas seule la structure du conflit.','across':'Les deux sources se complètent sur structure et expérience, mais leur convergence partielle ne résout pas automatiquement les heures ou responsabilités où leurs accès à l’information diffèrent.'},
 {'id':'fr-c1-u09-p05','seq':53,'title':'Cartographier un déplacement sans inventer les motifs','genre':'reflection','topics':['migration narrative','historical geography'],'paras':["Le dernier dossier suit le déplacement d’un groupe fictif à travers plusieurs lieux décrits dans des lettres et entretiens tardifs. Les sources nomment parfois une ville, parfois un repère vague, parfois seulement une direction relative. La reconstruction géographique doit donc distinguer localisation certaine, route probable et lieu encore indéterminé.","Les verbes de déplacement demandent également de la prudence. Une source peut dire qu’une personne a conduit un proche vers un autre lieu sans préciser si le déplacement était choisi, négocié ou imposé. La géographie ne suffit pas à reconstruire la motivation.","Le contreargument affirme qu’une carte avec trop de zones incertaines devient peu utile. Le rapport répond qu’une précision graphique fausse est plus dangereuse : elle transforme des hypothèses en faits visuellement convaincants. Il préfère donc des niveaux de confiance et des itinéraires alternatifs clairement marqués.","La conclusion relie espace et récit. Les lieux permettent de comparer des versions, de détecter des impossibilités chronologiques et de chercher de nouvelles archives, mais les motifs restent établis par d’autres éléments. La carte est un outil de raisonnement, pas un substitut au témoignage."],'qclaim':'Quelle distinction centrale organise la reconstruction géographique ?','aclaim':'Séparer lieu certain, route probable, repère vague et motivation du déplacement.','qinfer':'Pourquoi un verbe de déplacement ne prouve-t-il pas le consentement ?','ainfer':'Parce qu’il décrit le mouvement sans nécessairement expliquer la relation ou la contrainte qui l’a produit.','qassume':'Que suppose une carte honnête ?','aassume':'Des niveaux de confiance visibles plutôt que des localisations précises inventées pour remplir les lacunes.','qrelation':'Comment le texte répond-il à l’objection d’une carte incertaine ?','arelation':'Il préfère une incertitude visible à une précision fausse et utilise la carte pour guider d’autres recherches.','astance':'Employer la géographie comme contrainte et outil de comparaison sans lui faire expliquer seule les motifs.','asummary':'Cartographier aide à tester chronologie et versions, mais lieux, routes et motivations conservent des niveaux de preuve distincts.'}]
def checkpoint(groups,deck,lo,hi,theme,prior):
 forms=[f for k in ['p01','p02','p03','p04','p05'] for f in groups[k]];ps=["Le checkpoint propose un dossier fictif contenant un rapport officiel, deux lettres familiales, un journal local et une carte reconstruite plus tard. Toutes les sources parlent du même mois mais n’utilisent pas les mêmes repères temporels, les mêmes catégories d’acteurs ni les mêmes lieux.","Le lecteur construit d’abord une table d’affirmations : date, acteur, action, lieu, cause alléguée et niveau d’accès de chaque source. Cette opération révèle que certains désaccords portent sur des faits, tandis que d’autres viennent de vocabulaire ou de perspective.","La synthèse classe ensuite les conclusions par force. Quelques repères sont soutenus par plusieurs traces indépendantes; certaines expériences n’apparaissent que dans un témoignage mais restent crédibles dans son champ d’observation; plusieurs motivations demeurent ouvertes.","La conclusion historiographique refuse une histoire totale. Elle produit la reconstruction la mieux soutenue aujourd’hui et indique quels documents ou témoignages nouveaux pourraient déplacer la chronologie, la géographie ou l’attribution des responsabilités."];ps[1]+=' Révision cumulative : '+'; '.join(f'« {f} »' for f in forms)+'.';ps,text=fit(ps,lo,hi);P=base.prior(prior);rev=[base.rev(f,P) for f in forms];ids={t['form']:t['id'] for t in rev};items=[('main_claim','Quelle tâche organise le checkpoint ?','Comparer les affirmations de plusieurs sources selon provenance, accès, chronologie et contradiction.',[forms[0]]),('inference','Pourquoi certains désaccords ne sont-ils pas factuels ?','Parce qu’ils peuvent venir de catégories ou de perspectives différentes.',[forms[1]]),('assumption','Que suppose une forte corroboration ?','Des traces relativement indépendantes qui soutiennent la même affirmation précise.',[forms[8]]),('argument_relation','Comment les sources officielles et locales sont-elles reliées ?','Par leurs forces complémentaires et leurs limites d’accès différentes.',[forms[12]]),('stance','Quelle position historiographique domine ?','Une reconstruction graduée, explicite sur les lacunes et révisable.',[forms[16]]),('summary','Résume le checkpoint.','Décomposer les affirmations, comparer les sources, classer la force des conclusions et annoncer ce qui pourrait les réviser.',[forms[19]]),('vocabulary_in_context',f'Quel rôle joue « {forms[3]} » ?',USE[forms[3]],[forms[3]]),('vocabulary_in_context',f'Quel rôle joue « {forms[10]} » ?',USE[forms[10]],[forms[10]]),('vocabulary_in_context',f'Quel rôle joue « {forms[14]} » ?',USE[forms[14]],[forms[14]]),('synthesis','Quelle règle se transfère à un nouveau dossier historique ?','Ajuster chaque conclusion au type d’accès de la source, préserver les contradictions et rendre la révision possible.',[forms[6],forms[18]])];q,a=base.qa(items,ids)
 return {'id':'fr-c1-u09-p06','language':'fr','cefr':'C1','unit':9,'sequence':54,'revision':1,'title':'Checkpoint : reconstruire sans effacer les lacunes','passage_type':'checkpoint','genre':'historiographical essay','domains':['educational','public'],'topics':[theme,'cumulative historiography'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':[],'review_lexical_targets':rev,'grammar_targets':[{'id':'fr-c1-u09-p06-g1','role':'integration','description':'integrate temporal attribution, evidential scope and source perspective'}],'discourse_targets':[{'id':'fr-c1-u09-p06-d1','role':'integration','description':'synthesize provenance, contradiction, corroboration, uncertainty and revision'}],'questions':q,'answer_key':a,'speed_training':{'timed':True,'benchmark_eligible':True,'comprehension_gate':0.8,'new_word_policy':'none','notes':'C1 Unit09 zero-new checkpoint.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Fictional source-comparison checkpoint.']},'paired_text_group':None,'prerequisites':['French C1 Unit09 P01-P05'],'difficulty_notes_internal':'C1 cumulative historiography.','reader_tags':['unit_role:checkpoint','generation_batch','french_c1_u09']}
def main():
 raw=C1.read_text();rows=[json.loads(x) for x in raw.splitlines() if x.strip()];l=json.loads(LOCK.read_text());p=json.loads(PLAN.read_text());s=json.loads(SEL.read_text());c=h(C1);b=h(B2)
