 groups=s['passage_groups'];r=l['unit08_target_groups'];reviews={k:r[k] for k in ['p01','p02','p03','p04','p05']};deck=base.deck();lo,hi=s['word_band'];unit=[mk(x,groups[x['id'][-3:]],reviews[x['id'][-3:]],rows,deck,lo,hi,p['theme']) for x in specs()];unit.append(checkpoint(groups,deck,lo,hi,p['theme'],rows+unit));V=Draft202012Validator(json.loads(SCHEMA.read_text()))
